/** Jadual skor peranan (sunting sebaris), isi senarai standard dan padanan jawatan ikut nama. */
function roles_panel(array $roles): string {
    $h='<section class="panel spaced" id="peranan"><div class="panel-heading"><div><h3>Jadual skor peranan <span class="count">'.count($roles).'</span></h3><p class="muted">Pemberat jawatan diisi ikut peranan (Pengerusi 4, Ketua Panitia 5, Setiausaha 3, AJK 1 …). Menukar skor mengemas kini semua jawatan peranan itu.</p></div><div class="button-group">';
    if(count($roles)<count(ROLE_STANDARD)) $h.='<form method="post">'.csrf_field().'<input type="hidden" name="action" value="peranan_standard"><button class="btn sm outline" type="submit">'.icon('download').'Isi senarai standard</button></form>';
    if($roles) $h.='<a class="btn sm outline" href="/?page=jawatan&amp;padan=1#padan">Padankan jawatan ikut nama</a>';
    $h.='</div></div><div class="table-wrap"><table class="roles-table"><thead><tr><th>Peranan</th><th>Skor (1–10)</th><th>Jawatan</th><th><span class="sr-only">Tindakan</span></th></tr></thead><tbody>';
    foreach($roles as $r){ $f='peranan-'.(int)$r['id'];
        $h.='<tr><td><input form="'.$f.'" name="name" value="'.e($r['name']).'" maxlength="60" required aria-label="Nama peranan"></td><td><input form="'.$f.'" name="score" type="number" min="1" max="10" value="'.(int)$r['score'].'" required class="score-input" aria-label="Skor '.e($r['name']).'"></td><td>'.(int)$r['positions'].' jawatan</td>'
            .'<td><div class="row-actions"><form method="post" id="'.$f.'">'.csrf_field().'<input type="hidden" name="action" value="peranan_save"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="text-link link-button" type="submit">Simpan</button></form>'
            .engine_delete_button('peranan_delete',(int)$r['id'],'Padam peranan "'.$r['name'].'"?'.($r['positions']?' '.(int)$r['positions'].' jawatan kekal dengan pemberat semasa (tanpa peranan).':'')).'</div></td></tr>'; }
    if(!$roles) $h.='<tr><td colspan="4" class="muted">Belum ada peranan. Tekan <strong>Isi senarai standard</strong> atau tambah sendiri di bawah.</td></tr>';
    $h.='</tbody></table></div><form method="post" class="form-grid padded">'.csrf_field().'<input type="hidden" name="action" value="peranan_save"><input type="hidden" name="id" value="0"><label class="field">Peranan baharu<input name="name" maxlength="60" required placeholder="cth. Ketua Bidang"></label><label class="field">Skor<input name="score" type="number" min="1" max="10" value="3" required></label><div class="full form-actions"><button class="btn outline" type="submit">'.icon('plus').'Tambah peranan</button></div></form></section>';
    if(isset($_GET['padan']) && $roles){
        $m=roles_match_preview();
        $h.='<section class="panel spaced" id="padan"><div class="panel-heading"><div><h3>Padankan jawatan ikut nama <span class="count">'.count($m).'</span></h3><p class="muted">Jawatan tanpa peranan yang namanya bermula dengan nama peranan. Pemberat akan bertukar kepada skor peranan — semak sebelum menyimpan.</p></div><a class="text-link" href="/?page=jawatan#peranan">Tutup ×</a></div>';
        if(!$m) $h.='<p class="empty">Tiada jawatan yang sepadan dengan mana-mana peranan.</p>';
        else { $h.='<form method="post">'.csrf_field().'<input type="hidden" name="action" value="peranan_padan"><div class="table-wrap"><table><thead><tr><th><span class="sr-only">Pilih</span></th><th>Jawatan</th><th>Peranan</th><th>Pemberat</th></tr></thead><tbody>';
            foreach($m as $x) $h.='<tr><td><input type="checkbox" name="ids[]" value="'.(int)$x['position']['id'].'" checked aria-label="Padankan '.e($x['position']['name']).'"></td><td><strong>'.e($x['position']['name']).'</strong><small class="cell-sub">'.e($x['position']['category']).'</small></td><td>'.e($x['role']['name']).'</td><td>'.$x['weight_before'].' → <strong>'.$x['weight_after'].'</strong>'.($x['weight_before']!==$x['weight_after']?' <span class="badge warn">berubah</span>':'').'</td></tr>';
            $h.='</tbody></table></div><div class="form-actions padded"><button class="btn primary" type="submit">'.icon('check').'Padankan yang ditanda</button></div></form>'; }
        $h.='</section>';
    }
    return $h;
}
