/** Pemilih MP daripada katalog untuk medan kepakaran (JS menyegerakkan tanda ke input teks; tanpa JS guru menaip sendiri). */
function subject_picker(string $inputId,string $current): string {
    $subs=subjects_all(); if(!$subs) return '<small class="muted">Tiada senarai mata pelajaran. <a class="text-link" href="/?page=subjek">Sediakan senarai →</a></small>';
    $have=array_flip(array_map('mb_strtolower',specialty_tokens($current))); $by=[]; foreach($subs as $s) $by[$s['grp']!==''?$s['grp']:'Lain-lain'][]=$s['name'];
    $h='<details class="subject-pick" data-subject-pick="'.e($inputId).'"><summary>Pilih daripada senarai mata pelajaran</summary><div class="subject-pick-body">';
    foreach($by as $g=>$names){ $h.='<fieldset><legend>'.e($g).'</legend>'; foreach($names as $n) $h.='<label class="check"><input type="checkbox" value="'.e($n).'"'.(isset($have[mb_strtolower($n)])?' checked':'').'> '.e($n).'</label>'; $h.='</fieldset>'; }
    return $h.'</div></details>';
}
