function teacher_multi(string $name,array $selected,array $teachers): string {
    $h='<select name="'.e($name).'[]" multiple size="6" class="multi-select">'; foreach($teachers as $t) $h.='<option value="'.(int)$t['id'].'"'.(in_array((int)$t['id'],$selected,true)?' selected':'').'>'.e($t['name']).'</option>'; return $h.'</select>';
}
