<?php if($plan['warnings']): ?><details class="plan-details padded"><summary><?= count($plan['warnings']) ?> perhatian bagi lantikan sedia ada</summary><ul><?php foreach($plan['warnings'] as $w): ?><li><?= e($w) ?></li><?php endforeach; ?></ul></details><?php endif; ?>
<?php if($plan['unfilled']): ?><details class="plan-details padded" open><summary>Sebab jawatan belum diisi</summary><ul><?php foreach($plan['unfilled'] as $r): ?><li><strong><?= e($r['position_name']) ?></strong>: <?= e($r['reason']) ?></li><?php endforeach; ?></ul></details><?php endif; ?>
<div class="preview-tools padded"><label class="check"><input type="checkbox" data-change-filter<?= $plan['summary']['changed']?' checked':'' ?>> Paparkan perubahan sahaja</label><span class="muted"><?= (int)$plan['summary']['changed'] ?> perubahan daripada <?= count($plan['rows']) ?> jawatan</span></div>
<div class="table-wrap"><table id="jadual-pratonton"><thead><tr><th>Jawatan</th><th>Sebelum</th><th>Cadangan</th><th>Sebab / status</th></tr></thead><tbody><?php foreach($plan['rows'] as $r): ?><tr data-changed="<?= $r['changed']?'true':'false' ?>" class="<?= $r['changed']?'changed-row':'' ?>"<?= $plan['summary']['changed'] && !$r['changed']?' hidden':'' ?>><td><strong><?= e($r['position_name']) ?></strong><small class="cell-sub"><?= e($r['category']) ?> · <?= (int)$r['weight'] ?> mata</small></td><td><?= e($r['before_teacher_name']??'Kosong') ?></td><td><?= e($r['teacher_name']??'Belum diisi') ?></td><td><?= $r['changed']?'<span class="badge warn">Berubah</span> ':'' ?><?= e($r['reason']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<details class="plan-details padded"><summary>Beban guru selepas cadangan</summary><div class="table-wrap"><table><thead><tr><th>Guru</th><th>Mata / kapasiti</th><th>Bilangan tugas</th><th>Tugas berat</th></tr></thead><tbody><?php foreach($plan['teachers'] as $t): ?><tr><td><?= e($t['name']) ?></td><td><?= (int)$t['load'] ?> / <?= (int)$t['capacity'] ?></td><td><?= (int)$t['task_count'] ?></td><td><?= (int)$t['heavy'] ?></td></tr><?php endforeach; ?></tbody></table></div></details>
<form method="post" class="form-actions padded" data-confirm="Simpan perubahan agihan seperti dalam pratonton ini?"><?= csrf_field() ?><input type="hidden" name="action" value="auto_apply"><input type="hidden" name="plan_id" value="<?= e($plan['plan_id']) ?>"><span class="muted">Semak semua perubahan sebelum menyimpan.</span><button class="btn primary" type="submit"<?= !$plan['summary']['changed']?' disabled':'' ?>><?= icon('check') ?>Simpan agihan ini</button></form></section><?php endif;
}

/* ---------- Semakan & kelulusan ---------- */
function workflow_button(string $transition,string $label,array $state,string $style='primary'): string {
    return '<form method="post"'.($transition==='finalize'?' data-confirm="Muktamadkan versi ini dan terbitkan surat lantikan?"':'').'>'.csrf_field().'<input type="hidden" name="action" value="kelulusan"><input type="hidden" name="transition" value="'.$transition.'"><input type="hidden" name="version" value="'.(int)$state['version'].'"><button class="btn '.$style.'" type="submit">'.e($label).'</button></form>';
}
function kelulusan_page(array $user): void {
    $state=workflow_state(); $rev=$state['revision_id']?query('SELECT r.*,s.name AS submitter,a.name AS approver FROM workflow_revisions r JOIN users s ON s.id=r.submitted_by AND s.school_id=r.school_id LEFT JOIN users a ON a.id=r.approved_by AND a.school_id=r.school_id WHERE r.id=? AND r.school_id='.sid(),[$state['revision_id']])->fetch():null;
    $source=$state['status']==='draft' || !$rev?workflow_source():json_decode((string)$rev['payload'],true,64,JSON_THROW_ON_ERROR);
    $names=array_column($source['teachers'],'name','id'); $loads=array_fill_keys(array_column($source['teachers'],'id'),0); foreach($source['positions'] as $p) if($p['teacher_id']!==null) $loads[$p['teacher_id']]=($loads[$p['teacher_id']]??0)+$p['weight'];
    $over=array_filter($source['teachers'],fn($t)=>$loads[$t['id']]>$t['capacity']); $tasks=array_filter($source['positions'],fn($p)=>$p['teacher_id']!==null); $pub=workflow_published(); $keys=array_keys(WORKFLOW_LABELS);
    ?><div class="page-heading"><div><span class="eyebrow teal">KEPUTUSAN &amp; TANGGUNGJAWAB</span><h1>Semakan &amp; Kelulusan</h1><p class="muted">Semak agihan, rekod keputusan dan terbitkan lantikan rasmi sekolah.</p></div><span class="badge <?= $state['status']==='finalized'?'green':'warn' ?>"><?= e(WORKFLOW_LABELS[$state['status']]) ?></span></div>
<ol class="workflow-progress"><?php foreach(WORKFLOW_LABELS as $k=>$l): ?><li class="<?= $state['status']===$k?'current':(array_search($k,$keys)<array_search($state['status'],$keys)?'done':'') ?>"><span><?= array_search($k,$keys)+1 ?></span><strong><?= e($l) ?></strong></li><?php endforeach; ?></ol>
<?= $state['status']==='draft'?return_notice(workflow_return_info(),'kelulusan'):resubmit_notice(workflow_return_info('submitted')) ?>
<section class="panel"><div class="panel-heading"><div><h3><?= $state['status']==='draft'?'Draf agihan semasa':'Semakan versi #'.workflow_no((int)$state['revision_id']) ?></h3><p class="muted"><?= count($tasks) ?> lantikan · <?= count($source['positions'])-count($tasks) ?> jawatan kosong · Sesi <?= e($source['school']['year']) ?></p></div><?php if(can_plan($user) && $state['status']==='draft'): ?><a class="btn outline" href="/?page=agihan">Sunting draf</a><?php endif; ?></div>
<div class="padded workflow-note"><?php if($state['status']==='draft'): ?><p>Agihan masih boleh disunting oleh Pentadbir dan PK. Hantar draf untuk mengunci data dan mendapatkan semakan <?= e(head_title()) ?>.</p><?php elseif($rev): ?><p>Dihantar oleh <strong><?= e($rev['submitter']) ?></strong> pada <?= e(workflow_time($rev['submitted_at'])) ?>. Data dikunci sehingga dikembalikan kepada draf.</p><?php if($rev['approved_at']): ?><p>Diluluskan oleh <?= e($rev['approver']) ?> pada <?= e(workflow_time($rev['approved_at'])) ?>.</p><?php endif; endif; ?>
<p class="muted"><?= $pub?'Surat dan paparan guru menggunakan versi muktamad #'.(int)$pub['no'].'. Pindaan draf tidak mengubah dokumen yang telah diterbitkan.':'Belum ada versi muktamad. Surat lantikan dan tugas guru tersedia selepas pemuktamadan.' ?></p></div>
<?php if($over): ?><div class="notice error"><span><?= count($over) ?> guru melebihi kapasiti mata. Semak beban sebelum meluluskan.</span></div><?php endif; ?>
<?php $canReturn=$state['status']!=='draft' && in_array($user['role'],['admin','head'],true); ?>
<details class="plan-details padded"<?= $over || $canReturn?' open':'' ?>><summary>Beban guru dalam versi ini</summary><?php if($canReturn): ?><p class="muted small-note">Tanda guru yang bebannya perlu disemak semula oleh PK, kemudian tekan <strong><?= $state['status']==='finalized'?'Buka draf pindaan':'Kembalikan kepada draf' ?></strong> di bawah. Guru melebihi kapasiti ditanda secara automatik.</p><?php endif; ?><div class="table-wrap"><table class="load-review"><thead><tr><?php if($canReturn): ?><th><span class="sr-only">Tanda untuk semakan semula</span>Tanda</th><?php endif; ?><th>Guru</th><th>Mata / kapasiti</th><th>Status</th></tr></thead><tbody><?php foreach($source['teachers'] as $t): $isOver=$loads[$t['id']]>$t['capacity']; ?><tr class="<?= $isOver?'row-over':'' ?>"><?php if($canReturn): ?><td><input type="checkbox" name="flag[]" value="<?= (int)$t['id'] ?>" form="workflow-return" id="tanda-<?= (int)$t['id'] ?>"<?= $isOver?' checked':'' ?>></td><?php endif; ?><td><?php if($canReturn): ?><label for="tanda-<?= (int)$t['id'] ?>"><?= e($t['name']) ?></label><?php else: ?><?= e($t['name']) ?><?php endif; ?></td><td><?= (int)$loads[$t['id']] ?> / <?= (int)$t['capacity'] ?></td><td><?= $isOver?'<span class="badge warn">Melebihi kapasiti</span>':'Dalam kapasiti' ?></td></tr><?php endforeach; ?></tbody></table></div></details>
<div class="workflow-actions padded"><?php
    if($state['status']==='draft' && can_plan($user)) echo workflow_button('submit','Hantar untuk semakan',$state);
    if($user['role']==='head' && $state['status']==='submitted') echo workflow_button('approve','Luluskan agihan',$state);
    if($user['role']==='head' && $state['status']==='approved') echo workflow_button('finalize','Muktamadkan & terbitkan surat',$state);
    if($state['status']==='finalized') echo '<a class="btn primary" href="/?page=surat">Lihat surat muktamad</a>'; ?></div>
<?php if($canReturn): ?><form method="post" class="form-grid padded workflow-return" id="workflow-return"><?= csrf_field() ?><input type="hidden" name="action" value="kelulusan"><input type="hidden" name="transition" value="return"><input type="hidden" name="version" value="<?= (int)$state['version'] ?>"><label class="field full">Sebab dikembalikan / pindaan<input name="reason" required maxlength="500" placeholder="Cth. Kurangkan beban guru yang ditanda; pindahkan satu tugas HEM"></label><div class="full form-actions"><button class="btn outline" type="submit"><?= $state['status']==='finalized'?'Buka draf pindaan':'Kembalikan kepada draf' ?></button></div></form><?php endif; ?>
<div class="table-wrap"><table><thead><tr><th>Jawatan</th><th>Bidang</th><th>Pemberat</th><th>Penyandang</th></tr></thead><tbody><?php foreach($source['positions'] as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td><td><?= (int)$p['weight'] ?> mata</td><td><?= e($names[$p['teacher_id']??0]??'Belum diisi') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if(!feature_on('sejarah')): ?><p class="muted padded">Sejarah versi semakan tersedia untuk pakej Pro.</p><?php return; endif; ?>
<section class="panel spaced"><div class="panel-heading"><h3>Sejarah versi semakan</h3></div><div class="table-wrap"><table><thead><tr><th>Versi</th><th>Status</th><th>Penghantar</th><th>Tarikh dihantar</th><th>Sebab dikembalikan</th></tr></thead><tbody><?php foreach(query('SELECT r.id,r.status,r.submitted_at,r.return_reason,u.name,(SELECT COUNT(*) FROM workflow_revisions x WHERE x.school_id=r.school_id AND x.id<=r.id) AS no FROM workflow_revisions r JOIN users u ON u.id=r.submitted_by AND u.school_id=r.school_id WHERE r.school_id='.sid().' ORDER BY r.id DESC LIMIT 30')->fetchAll() as $r): ?><tr><td>#<?= (int)$r['no'] ?></td><td><?= e(WORKFLOW_LABELS[$r['status']]??'Dikembalikan') ?></td><td><?= e($r['name']) ?></td><td><?= e(workflow_time($r['submitted_at'])) ?></td><td><?= e($r['return_reason']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php
}

/* ---------- Surat ---------- */
function screen_letter(array $doc): string { return letter_html($doc,fn(array $a)=>branding_image_url($a)); }
function surat_page(): void {
    $pub=workflow_published(); $sel=(int)input('guru','get'); $all=isset($_GET['semua']);
    if(isset($_GET['contoh']) && can_plan()){ $docs=letter_sample(); ?><div class="page-heading no-print"><div><span class="eyebrow teal">PRATONTON FORMAT SEMASA</span><h1>Contoh Surat Lantikan</h1><p class="muted">Format &amp; profil draf semasa<?= count($docs)>1?' · '.count($docs).' surat (satu bagi setiap jawatan)':'' ?>. Surat sebenar menggunakan versi muktamad.</p></div><div class="button-group"><a class="btn outline" href="/?page=<?= current_user()['role']==='admin'?'sekolah':'surat' ?>">Kembali</a><button class="btn outline print-btn" type="button">Cetak</button></div></div><?php foreach($docs as $d) echo screen_letter($d); return; }
    ?><div class="page-heading no-print"><div><span class="eyebrow teal">DOKUMEN YANG TELAH DIMUKTAMADKAN</span><h1>Surat Lantikan</h1><p class="muted">Surat menggunakan salinan tetap agihan muktamad, termasuk nama sekolah dan <?= e(head_title()) ?>.</p></div><?php if($pub && feature_on('surat_pukal')): ?><div class="button-group"><a class="btn outline" href="/?page=surat&amp;semua=1">Semua surat</a><a class="btn outline" href="/?page=surat&amp;pdf=1<?= $sel?'&amp;guru='.$sel:'' ?>">↓ PDF<?= $sel?'':' (semua)' ?></a></div><?php elseif($pub): ?><span class="badge warn" title="Pakej Free: cetak surat seorang demi seorang">Surat pukal &amp; PDF · Pro</span><?php endif; ?></div>
<?php if(!$pub): ?><section class="panel padded empty"><h3>Belum ada agihan muktamad</h3><p>Hantar draf untuk semakan <?= e(head_title()) ?> dan muktamadkan sebelum menjana surat.</p><a class="btn outline" href="/?page=kelulusan">Semakan &amp; kelulusan</a></section><?php return; endif; ?>
<section class="panel padded no-print"><form method="get" class="search-form"><input type="hidden" name="page" value="surat"><label class="sr-only" for="surat-guru">Pilih guru</label><select id="surat-guru" name="guru" class="auto-submit" data-searchable="1"><option value="">Pilih nama guru</option><?php foreach($pub['data']['teachers'] as $t): ?><option value="<?= (int)$t['id'] ?>"<?= $sel===$t['id']?' selected':'' ?>><?= e($t['name']) ?></option><?php endforeach; ?></select><noscript><button class="btn primary">Pratonton</button></noscript><?php if($sel || $all): ?><button class="btn outline print-btn" type="button">Cetak</button><?php endif; ?></form><p class="muted">Versi muktamad #<?= (int)$pub['no'] ?>. <?= e(LETTER_MODES[$pub['data']['school']['letter']['mode']??'satu'][0]) ?>. Pindaan draf tidak mengubah surat ini sehingga versi baharu dimuktamadkan.<?php if(can_plan()): ?> <a class="text-link" href="/?page=surat&amp;contoh=1">Pratonton format semasa →</a><?php endif; ?></p></section>
<?php if($all && !feature_on('surat_pukal')){ pro_locked_panel('surat_pukal'); return; }
if($sel || $all){ $docs=letter_docs($pub,$all?null:$sel); foreach($docs as $d) echo screen_letter($d); if(!$docs) echo '<section class="panel padded empty"><p>Guru ini tiada lantikan dalam versi muktamad.</p></section>'; }
}
function tugas_saya_page(array $user): void {
    $pub=workflow_published(); $doc=null; $tid=(int)query('SELECT teacher_id FROM users WHERE id=? AND school_id='.sid(),[$user['id']])->fetchColumn();
    if($pub && $tid){ try { $doc=workflow_letter($tid,$pub); } catch(WorkflowError) {} }
    ?><div class="page-heading no-print"><div><span class="eyebrow teal">LANTIKAN SAYA</span><h1>Tugas Saya</h1><p class="muted">Selamat datang, <?= e($user['name']) ?>. Paparan ini menunjukkan tugas anda yang telah dimuktamadkan.</p></div><?php if($doc && $doc['assignments']): ?><div class="button-group"><button class="btn outline print-btn" type="button">Cetak</button><?php if(feature_on('surat_pukal')): ?><a class="btn primary" href="/?page=tugas_saya&amp;pdf=1">↓ PDF</a><?php endif; ?></div><?php endif; ?></div>
<?php if(!$tid): ?><section class="panel padded empty"><h3>Akaun belum dipautkan kepada profil guru</h3><p>Minta pentadbir sekolah memautkan akaun anda di Pengguna &amp; Audit.</p></section><?php elseif(!$doc || !$doc['assignments']): ?><section class="panel padded empty"><h3>Belum ada lantikan muktamad untuk anda</h3><p>Hubungi pentadbir sekolah jika anda memerlukan semakan.</p></section><?php else: foreach(letter_split($doc) as $d) echo screen_letter($d); endif;
}

