    $keys=query('SELECT k.*,u.name AS creator FROM api_keys k LEFT JOIN users u ON u.id=k.created_by AND u.school_id=k.school_id WHERE k.school_id='.sid().' ORDER BY k.revoked_at IS NOT NULL,k.id DESC')->fetchAll();
    $base=tenant_base_url().'/api/v1'; ?>
